command:
// Lean a little way around a corner without giving up the square you are standing in.
//
// Run it with one token selected and it offers every adjacent space that token could
// legally step into: nothing occupying it, no wall in the way, and no cutting a corner
// past one. Pick a space and the token shifts 15% of a square towards it and picks up a
// Peeking effect.
//
// Run it again while Peeking and the token drops the effect and settles back into the
// square it is still mostly standing in. No picker the second time.
//
// Two things end a peek without running this at all, both handled by the module rather
// than here, since a macro is not running when they happen:
//   moving the token to a different square drops the effect and leaves it where you put it
//   ending its turn while peeking settles it back and drops the effect
const M = 'draw-steel-combat-tools';
const api = game.modules.get(M)?.api;
if (!api) { ui.notifications.error('Draw Steel: Combat Tools is not active.'); return; }

// Distance and duration both come from the settings, so the macro and the house rule
// always agree. Distance is capped below half a square by the module.
const SHIFT = api.peek.distance();
const LEAN_MS = api.peek.duration();

const GS = canvas.grid.size;

const controlled = canvas.tokens.controlled;
if (controlled.length !== 1) {
  ui.notifications.warn(controlled.length
    ? 'Peek works from one token at a time. Select just the one doing the looking.'
    : 'Select the token doing the looking.');
  return;
}

const tok = controlled[0];
const act = tok.actor;
if (!act) { ui.notifications.warn('That token has no actor to carry the effect.'); return; }

// The module owns settling back, so this macro, the hook that fires on a manual move,
// and the one at the end of a turn all take the same path.
if (api.peek.isPeeking(act)) {
  await api.peek.unpeek(tok);
  ui.notifications.info(`${tok.name} stops peeking.`);
  return;
}

// The module works out which spaces are legal, so the macro and the house rule offer
// exactly the same set.
const candidates = api.peek.spaces(tok);

const GSZ = canvas.grid.size;
const w = Math.max(1, Math.round(tok.document.width));
const h = Math.max(1, Math.round(tok.document.height));
const from = { x: tok.document.x + (w * GSZ) / 2, y: tok.document.y + (h * GSZ) / 2 };

if (!candidates.length) {
  ui.notifications.warn(`${tok.name} has nowhere to peek from. Every space around it is blocked or occupied.`);
  return;
}

const chosen = await new Promise((resolve) => {
  const layer = new PIXI.Container();
  layer.eventMode = 'none';
  canvas.controls.addChild(layer);

  const g = new PIXI.Graphics();
  layer.addChild(g);

  let hover = null;
  const paint = () => {
    g.clear();
    for (const c of candidates) {
      const on = hover && hover.x === c.x && hover.y === c.y;
      g.lineStyle(on ? 3 : 2, on ? 0xffe066 : 0x66ccff, on ? 1 : 0.7);
      g.beginFill(on ? 0xffe066 : 0x66ccff, on ? 0.32 : 0.12);
      g.drawRoundedRect(c.x * GS + GS * 0.08, c.y * GS + GS * 0.08, GS * 0.84, GS * 0.84, 6);
      g.endFill();
    }
    if (!hover) return;
    // A stub of where the token would lean, so the 15% reads before committing to it.
    g.lineStyle(0);
    g.beginFill(0xffe066, 0.55);
    g.drawCircle(from.x + hover.dx * GS * SHIFT, from.y + hover.dy * GS * SHIFT, GS * 0.12);
    g.endFill();
  };

  const overlay = api.pickerOverlay.begin({
    title: `${tok.name} peeks around a corner`,
    status: 'Pick a space to lean towards.',
    detail: 'Escape or right click to stay put.',
    holeRects: [
      { x: tok.document.x, y: tok.document.y, w: w * GS, h: h * GS },
      ...candidates.map(c => ({ x: c.x * GS, y: c.y * GS, w: GS, h: GS })),
    ],
    showConfirm: false,
    showCancel: true,
    onCancel: () => done(null),
  });

  const atEvent = (event) => {
    const p = typeof event?.getLocalPosition === 'function' ? event.getLocalPosition(canvas.app.stage)
      : event?.data?.getLocalPosition ? event.data.getLocalPosition(canvas.app.stage)
      : canvas.app.renderer.events.pointer.getLocalPosition(canvas.app.stage);
    const o = canvas.grid.getOffset(p);
    return candidates.find(c => c.x === o.j && c.y === o.i) ?? null;
  };

  const onMove = (event) => { hover = atEvent(event); paint(); };
  const onDown = (event) => {
    if (event.target?.closest?.('#dsct-picker-topbar')) return;
    if (event.button === 2) { event.preventDefault(); done(null); return; }
    if (event.button !== 0) return;
    const pick = hover;
    if (!pick) return;
    event.preventDefault();
    event.stopPropagation();
    done(pick);
  };
  const onKey = (event) => { if (event.key === 'Escape') { event.preventDefault(); done(null); } };
  const onContext = (event) => event.preventDefault();

  function done(result) {
    canvas.stage.off('pointermove', onMove);
    window.removeEventListener('pointerdown', onDown, true);
    window.removeEventListener('keydown', onKey, true);
    window.removeEventListener('contextmenu', onContext, true);
    layer.parent?.removeChild(layer);
    layer.destroy({ children: true });
    overlay.end();
    resolve(result);
  }

  canvas.stage.on('pointermove', onMove);
  window.addEventListener('pointerdown', onDown, true);
  window.addEventListener('keydown', onKey, true);
  window.addEventListener('contextmenu', onContext, true);
  paint();
});

if (!chosen) return;

await api.peek.to(tok, chosen);

ui.notifications.info(`${tok.name} peeks.`);
